insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 25, 'Passe eu, rogo-te, e veja aquela terra boa, que está à parte ali do Jordão, aquele bom monte, e o Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 26, 'Mas o SENHOR se havia irado contra mim por causa de vós, pelo qual não me ouviu: e disse-me o SENHOR: Basta-te, não me fales mais deste negócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 27, 'Sobe ao cume do Pisga, e ergue teus olhos ao ocidente, e ao norte, e ao sul, e ao oriente, e vê por teus olhos: porque não passarás este Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 28, 'E manda a Josué, e anima-o, e conforta-o; porque ele há de passar diante deste povo, e ele lhes fará herdar a terra que verás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 29, 'E paramos no vale diante de Bete-Peor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 1, 'Agora, pois, ó Israel, ouve os estatutos e regulamentos que eu vos ensino, para que os executeis, e vivais, e entreis, e possuais a terra que o SENHOR o Deus de vossos pais te dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 2, 'Não acrescentareis à palavra que eu vos mando, nem diminuireis dela, para que guardeis os mandamentos do SENHOR vosso Deus que eu vos ordeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 3, 'Vossos olhos viram o que fez o SENHOR por motivo de Baal-Peor; que a todo homem que foi atrás de Baal-Peor destruiu o SENHOR teu Deus do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 4, 'Mas vós que vos achegastes ao SENHOR vosso Deus, todos estais vivos hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 5, 'Olhai, eu vos ensinei estatutos e regulamentos, como o SENHOR meu Deus me mandou, para que façais assim em meio da terra na qual entrais para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 6, 'Guardai-os, pois, e ponde-os por obra: porque esta é vossa sabedoria e vossa inteligência aos olhos dos povos, os quais ouvirão todos estes estatutos, e dirão: Certamente povo sábio e entendido, gente grande é esta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 7, 'Porque que gente grande há que tenha os deuses próximo a si, como o está o SENHOR nosso Deus em tudo quanto lhe pedimos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 8, 'E que gente grande há que tenha estatutos e regulamentos justos, como é toda esta lei que eu ponho hoje diante de vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 9, 'Portanto, guarda-te, e guarda tua alma com empenho, que não te esqueças das coisas que teus olhos viram, nem se apartem de teu coração todos os dias de tua vida: e as ensinarás a teus filhos, e aos filhos de teus filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 10, 'No dia que estiveste diante do SENHOR teu Deus em Horebe, quando o SENHOR me disse: Junta-me o povo, para que eu lhes faça ouvir minhas palavras, as quais aprenderão, para temer-me todos os dias que viverem sobre a terra: e as ensinarão a seus filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 11, 'E vos aproximastes, e vos pusestes ao pé do monte; e o monte ardia em fogo até em meio dos céus com trevas, nuvem, e escuridão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 12, 'E falou o SENHOR convosco do meio do fogo: ouvistes a voz de suas palavras, mas a exceção de ouvir a voz, nenhuma forma vistes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 13, 'E ele vos anunciou seu pacto, o qual vos mandou pôr por obra, os dez mandamentos; e escreveu-os em duas tábuas de pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 14, 'A mim também me mandou o SENHOR então ensinar-vos os estatutos e regulamentos, para que os pusestes por obra na terra à qual passais para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 15, 'Guardai pois muito vossas almas: pois nenhuma forma vistes no dia que o SENHOR falou convosco do meio do fogo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 16, 'Para que não vos corrompais, e façais para vós escultura, imagem de forma alguma, efígie de macho ou fêmea,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 17, 'Figura de algum animal que seja na terra, forma de ave alguma de asas que voe pelo ar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 18, 'Figura de nenhum animal que vá arrastando pela terra, forma de peixe algum que haja na água debaixo da terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 19, 'E para que levantando teus olhos ao céu, e vendo o sol e a lua e as estrelas, e todo o exército do céu, não sejas incitado, e te inclines a eles, e lhes sirvas; que o SENHOR teu Deus os concedeu a todos os povos debaixo de todos os céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 20, 'Porém a vós o SENHOR vos tomou, e vos tirou do forno de ferro, do Egito, para que lhe sejais por povo de herança como neste dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 21, 'E o SENHOR se irou contra mim sobre vossos negócios, e jurou que eu não passaria o Jordão, nem entraria na boa terra, que o SENHOR teu Deus te dá por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 22, 'Assim eu vou a morrer nesta terra; e não passo o Jordão: mas vós passareis, e possuireis aquela boa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 23, 'Guardai-vos que não vos esqueçais do pacto do SENHOR vosso Deus, que ele estabeleceu convosco, e vos façais escultura ou imagem de qualquer coisa, que o SENHOR teu Deus te proibiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 24, 'Porque o SENHOR teu Deus é fogo que consome, Deus zeloso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 25, 'Quando houverdes gerado filhos e netos, e houverdes envelhecido na terra, e vos corromperdes, e fizerdes escultura ou imagem de qualquer coisa, e fizerdes mal aos olhos do SENHOR vosso Deus, para irá-lo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 26, 'Eu ponho hoje por testemunhas ao céu e à terra, que logo perecereis totalmente da terra até a qual passais o Jordão para possuí-la: não estareis nela longos dias sem que sejais destruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 27, 'E o SENHOR vos espalhará entre os povos, e restareis poucos em número entre as nações às quais vos levará o SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 28, 'E servireis ali a deuses feitos das mãos de homens, a madeira e a pedra, que não vem, nem ouvem, nem comem, nem cheiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 29, 'Mas se desde ali buscares ao SENHOR teu Deus, o acharás, se o buscares de todo teu coração e de toda tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 30, 'Quando estiveres em angústia, e te alcançarem todas estas coisas, se nos últimos dias te voltares ao SENHOR teu Deus, e ouvires sua voz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 31, 'Porque Deus misericordioso é o SENHOR teu Deus; não te deixará, nem te destruirá, nem se esquecerá do pacto de teus pais que lhes jurou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 32, 'Porque pergunta agora dos tempos passados, que foram antes de ti, desde o dia que criou Deus ao homem sobre a terra, e desde um fim do céu ao outro, se se fez coisa semelhante a esta grande coisa, ou se tenha ouvido outra como ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 33, 'Ouviu povo a voz de Deus, que falasse do meio do fogo, como tu a ouviste, e viveste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 34, 'Ou experimentou Deus a vir a tomar para si nação do meio de outra nação, com provas, com sinais, com milagres, e com guerra, e mão forte, e braço estendido, e grandes espantos, segundo todas as coisas que fez convosco o SENHOR vosso Deus no Egito diante de teus olhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 35, 'A ti te foi mostrado, para que soubesses que o SENHOR ele é Deus; não há mais além dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 36, 'Dos céus te fez ouvir sua voz, para ensinar-te: e sobre a terra te mostrou seu grande fogo: e ouviste suas palavras do meio do fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 37, 'E porquanto ele amou a teus pais, escolheu sua descendência depois deles, e te tirou diante de si do Egito com seu grande poder;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 38, 'Para lançar de diante de ti nações grandes e mais fortes que tu, e para te introduzir, e dar-te sua terra por herança, como hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 39, 'Aprende pois hoje, e medita em teu coração que o SENHOR ele é o Deus acima no céu, e abaixo sobre a terra; não há outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 40, 'E guarda seus estatutos e seus mandamentos, que eu te mando hoje, para que te vá bem a ti e a teus filhos depois de ti, e prolongues teus dias sobre a terra que o SENHOR teu Deus te dá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 41, 'Então separou Moisés três cidades desta parte do Jordão ao oriente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 42, 'Para que fugisse ali o homicida que matasse a seu próximo por acidente, sem haver tido inimizade com ele desde ontem nem antes de ontem; e que fugindo de uma vez destas cidades salvara a vida:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 43, 'A Bezer no deserto, em terra da planície, dos rubenitas; e a Ramote em Gileade, dos gaditas; e a Golã em Basã, dos de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 44, 'Esta, pois, é a lei que Moisés propôs diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 45, 'Estes são os testemunhos, e os estatutos, e os regulamentos, que Moisés notificou aos filhos de Israel, quando houveram saído do Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 46, 'Desta parte do Jordão, no vale diante de Bete-Peor, na terra de Seom rei dos amorreus, que habitava em Hesbom, ao qual feriu Moisés com os filhos de Israel, quando saíram do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 47, 'E possuíram sua terra, e a terra de Ogue rei de Basã; dois reis dos amorreus que estavam desta parte do Jordão, ao oriente:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 48, 'Desde Aroer, que está junto à beira do ribeiro de Arnom, até o monte de Sião, que é Hermom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 4, 49, 'E toda a planície desta parte do Jordão, ao oriente, até o mar da planície, as encostas das águas abaixo do Pisga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 1, 'E chamou Moisés a todo Israel, e disse-lhes: Ouve, Israel, os estatutos e regulamentos que eu pronuncio hoje em vossos ouvidos: e aprendei-os, e guardai-os, para praticá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 2, 'O SENHOR nosso Deus fez pacto conosco em Horebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 3, 'Não com nossos pais fez o SENHOR este pacto, a não ser conosco todos os que estamos aqui hoje vivos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 4, 'Face a face falou o SENHOR convosco no monte do meio do fogo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 5, '(Eu estava então entre o SENHOR e vós, para vos anunciar a palavra do SENHOR; porque vós tivestes temor do fogo, e não subistes ao monte;) dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 6, 'Eu sou o SENHOR teu Deus, que te tirei da terra do Egito, de casa de servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 7, 'Não terás deuses estranhos diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 8, 'Não farás para ti escultura, nem imagem alguma de coisa que está acima nos céus, ou abaixo na terra, ou nas águas debaixo da terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 9, 'Não te inclinarás a elas nem lhes servirás: porque eu sou o SENHOR teu Deus, forte, zeloso, que visito a iniquidade dos pais sobre os filhos, e sobre a terceira geração, e sobre a quarta, aos que me aborrecem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 10, 'E que faço misericórdia a milhares aos que me amam, e guardam meus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 11, 'Não tomarás em vão o nome do SENHOR teu Deus; porque o SENHOR não dará por inocente ao que tomar em vão seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 12, 'Guardarás o dia do repouso para santificá-lo, como o SENHOR teu Deus te mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 13, 'Seis dias trabalharás e farás toda tua obra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 14, 'Mas no sétimo é repouso ao SENHOR teu Deus: nenhuma obra farás tu, nem teu filho, nem tua filha, nem teu servo, nem tua serva, nem tua boi, nem tua asno, nem nenhum animal teu, nem tua peregrino que está dentro de tuas portas: para que descanse teu servo e tua serva como'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 15, 'E lembra-te que foste servo em terra do Egito, e que o SENHOR teu Deus te tirou dali com mão forte e braço estendido: pelo qual o SENHOR teu Deus te mandou que guardes no dia do repouso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 16, 'Honra a teu pai e a tua mãe, como o SENHOR teu Deus te mandou, para que sejam prolongados teus dias, e para que te vá bem sobre a terra que o SENHOR teu Deus te dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 17, 'Não cometerás homicídio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 18, 'Não adulterarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 19, 'Não furtarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 20, 'Não dirás falso testemunho contra teu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 21, 'Não cobiçarás a mulher de teu próximo, nem desejarás a casa de teu próximo, nem sua terra, nem seu servo, nem sua serva, nem seu boi, nem seu asno, nem nenhuma coisa que seja de teu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 22, 'Estas palavras falou o SENHOR a toda vossa congregação no monte, do meio do fogo, da nuvem e da escuridão, a grande voz: e não acrescentou mais. E escreveu-os em duas tábuas de pedra, as quais deu a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 23, 'E aconteceu, que como vós ouvistes a voz do meio das trevas, e vistes ao monte que ardia em fogo, aproximastes a mim todos os príncipes de vossas tribos, e vossos anciãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 24, 'E dissestes: Eis que, o SENHOR nosso Deus nos mostrou sua glória e sua grandeza, e ouvimos sua voz do meio do fogo: hoje vimos que o SENHOR fala ao homem, e este vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 25, 'Agora pois, por que morreremos? Que este grande fogo nos consumirá: se voltarmos a ouvir a voz do SENHOR nosso Deus, morreremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 26, 'Porque, que é toda carne, para que ouça a voz do Deus vivente que fala do meio do fogo, como nós a ouvimos, e viva?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 27, 'Chega tu, e ouve todas as coisas que disser o SENHOR nosso Deus; e tu nos dirás todo o que o SENHOR nosso Deus te disser, e nós ouviremos e faremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 28, 'E ouviu o SENHOR a voz de vossas palavras, quando me faláveis; e disse-me o SENHOR: Ouvi a voz das palavras deste povo, que eles te falaram: bem está tudo o que disseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 29, 'Quem dera que tivessem tal coração, que me temessem, e guardassem todos os dias todos meus mandamentos, para que a eles e a seus filhos lhes fosse bem para sempre!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 30, 'Vai, dize-lhes: Voltai-vos a vossas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 31, 'E tu fica aqui comigo, e te direi todos os mandamentos, e estatutos, e regulamentos que lhes hás de ensinar, a fim que os ponham agora por obra na terra que eu lhes dou para possuí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 32, 'Olhai, pois, que façais como o SENHOR vosso Deus vos mandou: não vos desvieis à direita nem à esquerda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 5, 33, 'Andai em todo caminho que o SENHOR vosso Deus vos mandou, para que vivais, e vos vá bem, e tenhais longos dias na terra que haveis de possuir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 1, 'Estes, pois são os mandamentos, estatutos, e regulamentos que o SENHOR vosso Deus mandou que vos ensinasse, para que os ponhais por obra na terra à qual passais vós para possuí-la:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 2, 'Para que temas ao SENHOR teu Deus, guardando todos os seus estatutos e seus mandamentos que eu te mando, tu, e teu filho, e o filho de teu filho, todos os dias de tua vida, e que teus dias sejam prolongados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 3, 'Ouve, pois, ó Israel, e cuida de praticá-los, para que te vá bem, e sejais multiplicados, como te disse o SENHOR o Deus de teus pais, na terra que destila leite e mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 4, 'Ouve, Israel: o SENHOR nosso Deus, o SENHOR um é:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 5, 'E Amarás ao SENHOR teu Deus de todo teu coração, e de toda tua alma, e com todo tua poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 6, 'E estas palavras que eu te mando hoje, estarão sobre teu coração:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 7, 'E as repetirás a teus filhos, e falarás delas estando em tua casa, e andando pelo caminho, e ao deitar-te, e quando te levantes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 8, 'E hás de atá-las por sinal em tua mão, e estarão por frontais entre teus olhos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 9, 'E as escreverás nos umbrais de tua casa, e em tuas entradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 10, 'E será, quando o SENHOR teu Deus te houver introduzido na terra que jurou a teus pais Abraão, Isaque, e Jacó, que te daria; em cidades grandes e boas que tu não edificaste,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 11, 'E casas cheias de todo ainda que tu não encheste, e cisternas cavadas, que tu não cavaste, vinhas e olivais que não plantaste: logo que comeres e te fartares,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 12, 'Guarda-te que não te esqueças do SENHOR, que te tirou da terra do Egito, de casa de servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 13, 'Ao SENHOR teu Deus temerás, e a ele servirás, e por seu nome jurarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 14, 'Não andareis após deuses alheios, dos deuses dos povos que estão em vossos entornos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 15, 'Porque o Deus zeloso, o SENHOR teu Deus, em meio de ti está; para que não se inflame o furor do SENHOR teu Deus contra ti, e te destrua de sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 16, 'Não tentareis ao SENHOR vosso Deus, como o tentastes em Massá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 17, 'Guardai cuidadosamente os mandamentos do SENHOR vosso Deus, e seus testemunhos, e seus estatutos, que te mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 18, 'E farás o correto e bom aos olhos do SENHOR, para que te vá bem, e entres e possuas a boa terra que o SENHOR jurou a teus pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 19, 'Para que ele expulse a todos os seus inimigos de diante de ti, como o SENHOR disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 20, 'Quando amanhã te perguntar teu filho, dizendo: Que significam os testemunhos, e estatutos, e regulamentos, que o SENHOR nosso Deus vos mandou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 21, 'Então dirás a teu filho: Nós éramos servos de Faraó no Egito, e o SENHOR tirou do Egito com mão forte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 22, 'E deu o SENHOR sinais e milagres grandes e nocivos no Egito, sobre Faraó e sobre toda sua casa, diante de nossos olhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 23, 'E tirou-nos dali, para trazer-nos e dar-nos a terra que jurou a nossos pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 24, 'E mandou-nos o SENHOR que executássemos todos estes estatutos, e que temamos ao SENHOR nosso Deus, para que nos vá bem todos os dias, e para que nos dê vida, como hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 6, 25, 'E teremos justiça quando cuidarmos de pôr por obra todos estes mandamentos diante do SENHOR nosso Deus, como ele nos mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 1, 'Quando o SENHOR teu Deus te houver introduzido na terra na qual tu hás de entrar para possuí-la, e houver expulsado de diante de ti muitas nações, aos heteus, aos gergeseus, e aos amorreus, e aos cananeus, e aos perizeus, e aos heveus, e aos jebuseus, sete nações maiores e mais fortes que tu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 2, 'E o SENHOR teu Deus as houver entregue diante de ti, e as ferires, por completo as destruirás: não farás com eles aliança, nem as pouparás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 3, 'E não aparentarás com eles: não darás tua filha a seu filho, nem tomarás a sua filha para teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 4, 'Porque desviará a teu filho de me seguir, e servirão a deuses alheios; e o furor do SENHOR se acenderá sobre vós, e te destruirá logo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 5, 'Mas assim haveis de fazer com eles: destruireis seus altares, e quebrareis suas colunas sagradas, cortareis seus mastros de idolatria, e queimareis suas esculturas a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 6, 'Porque tu és povo santo ao SENHOR teu Deus: o SENHOR teu Deus te escolheu para ser-lhe um povo especial, mais que todos os povos que estão sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 7, 'Não por ser vós mais que todos os povos vos quis o SENHOR, e vos escolheu; porque vós éreis os menores de todos os povos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 8, 'Mas sim porque o SENHOR vos amou, e quis guardar o juramento que jurou a vossos pais, vos tirou o SENHOR com mão forte, e vos resgatou de casa de servos, da mão de Faraó, rei do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 9, 'Conhece, pois, que o SENHOR teu Deus é Deus, Deus fiel, que guarda o pacto e a misericórdia aos que lhe amam e guardam seus mandamentos, até as mil gerações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 10, 'E que retribui em sua face ao que lhe aborrece, destruindo-o: nem o dilatará ao que lhe odeia, em sua face lhe retribuirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 11, 'Guarda portanto os mandamentos, e estatutos, e regulamentos que eu te mando hoje que cumpras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 12, 'E será que, por haver ouvido estes regulamentos, e guardado e os praticado, o SENHOR teu Deus guardará contigo o pacto e a misericórdia que jurou a teus pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 13, 'E te amará, e te abençoará, e te multiplicará, e abençoará o fruto de teu ventre, e o fruto de tua terra, e teu grão, e teu mosto, e teu azeite, a cria de tuas vacas, e os rebanhos de tuas ovelhas, na terra que jurou a teus pais que te daria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 14, 'Bendito serás mais que todos os povos: não haverá em ti homem nem mulher estéril, nem em teus animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 15, 'E tirará o SENHOR de ti toda enfermidade; e todas as más pragas do Egito, que tu sabes, não as porá sobre ti, antes as porá sobre todos os que te odiarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 16, 'E consumirás a todos os povos que te dá o SENHOR teu Deus: não os perdoará teu olho; nem servirás a seus deuses, que te será tropeço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 17, 'Quando disseres em teu coração: Estas nações são muitas mais que eu, como as poderei desarraigar?;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 18, 'Não tenhas medo deles: lembra-te bem do que fez o SENHOR teu Deus com Faraó e com todo o Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 19, 'Das grandes provas que viram teus olhos, e dos sinais e milagres, e da mão forte e braço estendido com que o SENHOR teu Deus te tirou: assim fará o SENHOR teu Deus com todos os povos de cuja presença tu temerdes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 20, 'E também enviará o SENHOR teu Deus sobre eles vespas, até que pereçam os que restarem, e os que se houverem escondido de diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 21, 'Não desmaies diante deles, que o SENHOR teu Deus está em meio de ti, Deus grande e terrível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 22, 'E o SENHOR teu Deus expulsará a estas nações de diante de ti pouco a pouco: não as poderás acabar logo, para que os animais do campo não se aumentem contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 23, 'Mas o SENHOR teu Deus as entregará diante de ti, e ele as quebrantará com grande destroço, até que sejam destruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 24, 'E ele entregará seus reis em tua mão, e tu destruirás o nome deles de debaixo do céu: ninguém te fará testa até que os destruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 25, 'As esculturas de seus deuses queimarás no fogo: não cobiçarás prata nem ouro de sobre elas para tomá-lo para ti, para que não tropeces nisso, pois é abominação ao SENHOR teu Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 7, 26, 'E não meterás abominação em tua casa, para que não sejas anátema como isso; por completo o aborrecerás e o abominarás; porque é anátema.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 1, 'Cuidareis de pôr por obra todo mandamento que eu vos ordeno hoje, para que vivais, e sejais multiplicados, e entreis, e possuais a terra, da qual jurou o SENHOR a vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 2, 'E te lembrarás de todo o caminho por onde te trouxe o SENHOR teu Deus estes quarenta anos no deserto, para afligir-te, para provar-te, para saber o que estava em teu coração, se havias de guardar ou não seus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 3, 'E te afligiu, e te fez ter fome, e te sustentou com maná, comida que não conhecias tu, nem teus pais a conheciam; para fazer-te saber que o homem não viverá de só pão, mas de tudo o que sai da boca do SENHOR viverá o homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 4, 'Tua roupa nunca se envelheceu sobre ti, nem o pé se te inchou por estes quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 5, 'Reconhece assim em teu coração, que como castiga o homem a seu filho, assim o SENHOR teu Deus te castiga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 6, 'Guardarás, pois, os mandamentos do SENHOR teu Deus, andando em seus caminhos, e temendo-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 7, 'Porque o SENHOR teu Deus te introduz na boa terra, terra de ribeiros, de águas, de fontes, de mananciais que brotam por planícies e montes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 8, 'Terra de trigo e cevada, e de videiras, e figueiras, e romeiras; terra de olivas, de azeite, e de mel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 9, 'Terra na qual não comerás o pão com escassez, não te faltará nada nela; terra que suas pedras são ferro, e de seus montes cortarás bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 10, 'E comerás e te fartarás, e bendirás ao SENHOR teu Deus pela boa terra que te haverá dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 11, 'Guarda-te, que não te esqueças do SENHOR teu Deus, para não observar seus mandamentos, e seus regulamentos, e seus estatutos, que eu te ordeno hoje:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 12, 'Para que não aconteça talvez que comas e te fartes, e edifiques boas casas em que mores,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 13, 'E tuas vacas e tuas ovelhas se aumentem, e a prata e o ouro se te multiplique, e tudo o que tiveres se te aumente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 14, 'E se eleve logo teu coração, e te esqueças do SENHOR teu Deus, que te tirou da terra do Egito, de casa de servos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 15, 'Que te fez caminhar por um deserto grande e espantoso, de serpentes ardentes, e de escorpiões, e de sede, onde nenhuma água havia, e ele te tirou água da rocha de pederneiras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 16, 'Que te sustentou com maná no deserto, comida que teus pais não conheciam, afligindo-te e provando-te, para ao fim fazer-te bem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 17, 'E digas em teu coração: Meu poder e a força de minha mão me trouxeram esta riqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 18, 'Antes lembra-te do SENHOR teu Deus: porque ele te dá o poder para fazer as riquezas, a fim de confirmar seu pacto que jurou a teus pais, como neste dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 19, 'Mas será, se chegares a esquecer-te do SENHOR teu Deus, e andares atrás de deuses alheios, e lhes servires, e a eles te encurvares, atesto-o hoje contra vós, que certamente perecereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 8, 20, 'Como as nações que o SENHOR destruirá diante de vós, assim perecereis; porquanto não havereis atendido à voz do SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 1, 'Ouve, Israel: tu estás hoje para passar o Jordão, para entrar a possuir nações mais numerosas e mais fortes que tu, cidades grandes e fortificadas até o céu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 2, 'Um povo grande e alto, filhos de gigantes, dos quais tens tu conhecimento, e ouviste dizer: Quem resistirá diante dos filhos do gigante?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 3, 'Sabe, pois, hoje que o SENHOR teu Deus é o que passa diante de ti, fogo consumidor, que os destruirá e humilhará diante de ti: e tu os expulsarás, e os destruirás logo, como o SENHOR te disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 4, 'Não digas em teu coração quando o SENHOR teu Deus os haverá expulsado de diante de ti, dizendo: Por minha justiça me pôs o SENHOR a possuir esta terra; pois pela impiedade destas nações o SENHOR as expulsa de diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 5, 'Não por tua justiça, nem pela retidão de teu coração entras a possuir a terra deles; mas pela impiedade destas nações o SENHOR teu Deus as expulsa de diante de ti, e para confirmar a palavra que o SENHOR jurou a teus pais Abraão, Isaque, e Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 6, 'Portanto, sabe que não por tua justiça o SENHOR teu Deus te dá esta boa terra para possuí-la; que povo duro de cerviz és tu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 7, 'Lembra-te, não te esqueças que provocaste a ira ao SENHOR teu Deus no deserto: desde o dia que saíste da terra do Egito, até que entrastes neste lugar, fostes rebeldes ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 8, 'E em Horebe provocastes à ira ao SENHOR, e irou-se o SENHOR contra vós para destruir-vos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 9, 'Quando eu subi ao monte para receber as tábuas de pedra, as tábuas do pacto que o SENHOR fez convosco, estive então no monte quarenta dias e quarenta noites, sem comer pão nem beber água:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 10, 'E deu-me o SENHOR as duas tábuas de pedra escritas com o dedo de Deus; e nelas estava escrito conforme todas as palavras que vos falou o SENHOR no monte do meio do fogo, no dia da assembleia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 11, 'E foi ao fim dos quarenta dias e quarenta noites, que o SENHOR me deu as duas tábuas de pedra, as tábuas do pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 12, 'E disse-me o SENHOR: Levanta-te, desce logo daqui; que teu povo que tiraste do Egito se corrompeu: logo se apartaram do caminho que eu lhes mandei: fizeram para si uma efígie de fundição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 13, 'E falou-me o SENHOR, dizendo: Vi esse povo, e eis que ele é povo duro de cerviz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 14, 'Deixa-me que os destrua, e apague seu nome de debaixo do céu; que eu te porei sobre gente forte e muito mais que eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 15, 'E voltei e desci do monte, o qual ardia em fogo, com as tábuas do pacto em minhas duas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 16, 'E olhei, e eis que havíeis pecado contra o SENHOR vosso Deus: Havíeis feito para vós um bezerro de fundição, desviando-vos logo do caminho que o SENHOR vos havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 17, 'Então tomei as duas tábuas, e lancei-as de minhas duas mãos, e quebrei-as diante vossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 18, 'E prostrei-me diante do SENHOR, como antes, quarenta dias e quarenta noites: não comi pão nem bebi água, por causa de todo vosso pecado que havíeis cometido fazendo mal aos olhos do SENHOR para irá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 19, 'Porque temi por causa do furor e da ira com que o SENHOR estava irritado contra vós para destruir-vos. Porém o SENHOR me ouviu ainda esta vez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 20, 'Contra Arão também se irou o SENHOR em grande maneira para destruí-lo: e também orei por Arão então.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 21, 'E tomei vosso pecado, o bezerro que havíeis feito, e queimei no fogo, e o esmigalhei moendo-o muito bem, até que foi reduzido a pó: e lancei o pó dele no ribeiro que descia do monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 22, 'Também em Taberá, e em Massá, e em Quibrote-Hataavá, irritastes ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 23, 'E quando o SENHOR vos enviou desde Cades-Barneia, dizendo: Subi e possuí a terra que eu vos dei; também fostes rebeldes ao dito do SENHOR vosso Deus, e não o crestes, nem obedecestes à sua voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 24, 'Rebeldes fostes ao SENHOR desde o dia que eu vos conheço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 25, 'Prostrei-me, pois, diante do SENHOR quarenta dias e quarenta noites que estive prostrado; porque o SENHOR disse que vos havia de destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 26, 'E orei ao SENHOR, dizendo: Ó Senhor DEUS, não destruas teu povo e tua herança que resgataste com tua grandeza, ao qual tiraste do Egito com mão forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 27, 'Lembra-te de teus servos Abraão, Isaque, e Jacó; não olhes à dureza deste povo, nem a sua impiedade, nem a seu pecado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 28, 'Porque não digam os da terra de onde nos tiraste: Porquanto não pôde o SENHOR introduzi-los na terra que lhes havia dito, ou porque os aborrecia, os tirou para matá-los no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 9, 29, 'E eles são teu povo e tua herança, que tiraste com tua grande força e com teu braço estendido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 1, 'Naquele tempo o SENHOR me disse: Lavra para ti duas tábuas de pedra como as primeiras, e sobe a mim ao monte, e faze para ti uma arca de madeira:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 2, 'E escreverei naquelas tábuas palavras que estavam nas tábuas primeiras que quebraste; e as porás na arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 3, 'E fiz uma arca de madeira de acácia, e lavrei duas tábuas de pedra como as primeiras, e subi ao monte com as duas tábuas em minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 4, 'E escreveu nas tábuas conforme a primeira escritura, os dez mandamentos que o SENHOR vos havia falado no monte do meio do fogo, no dia da assembleia; e as deu a mim o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 5, 'E voltei e desci do monte, e pus as tábuas na arca que havia feito; e ali estão, como o SENHOR me mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 6, '(Depois partiram os filhos de Israel de Beerote-Bene-Jacacã a Moserá: ali morreu Arão, e ali foi sepultado; e em lugar seu teve o sacerdócio seu filho Eleazar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 7, 'De ali partiram a Gudgodá, e de Gudgodá a Jotbatá, terra de ribeiros de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 8, 'Naquele tempo separou o SENHOR a tribo de Levi, para que levasse a arca do pacto do SENHOR, para que estivesse diante do SENHOR para servir-lhe, e para abençoar em seu nome, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 9, 'Pelo qual Levi não teve parte nem herança com seus irmãos: o SENHOR é sua herança, como o SENHOR teu Deus lhe disse.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 10, 'E eu estive no monte como os primeiros dias, quarenta dias e quarenta noites; e o SENHOR me ouviu também esta vez, e não quis o SENHOR destruir-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 11, 'E disse-me o SENHOR: Levanta-te, anda, para que partas diante do povo, para que entrem e possuam a terra que jurei a seus pais lhes havia de dar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 12, 'Agora, pois, Israel, que pede o SENHOR teu Deus de ti, a não ser que temas ao SENHOR teu Deus, que andes em todos os seus caminhos, e que o ames, e sirvas ao SENHOR teu Deus contudo teu coração, e com toda tua alma;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 13, 'Que guardes os mandamentos do SENHOR e seus estatutos, que eu te prescrevo hoje, para que tenhas bem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 14, 'Eis que, do SENHOR teu Deus são os céus, e os céus dos céus: a terra, e todas as coisas que há nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 15, 'Somente de teus pais se agradou o SENHOR para amá-los, e escolheu sua descendência depois deles, a vós, dentre todos os povos, como neste dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 16, 'Circuncidai pois o prepúcio de vosso coração, e não endureçais mais vossa cerviz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 17, 'Porque o SENHOR vosso Deus é Deus de deuses, e Senhor de senhores, Deus grande, poderoso, e terrível, que não faz acepção de pessoas, nem toma suborno;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 18, 'Que faz justiça ao órfão e à viúva; que ama também ao estrangeiro dando-lhe pão e roupa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 19, 'Amareis pois ao estrangeiro: porque estrangeiros fostes vós em terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 20, 'Ao SENHOR teu Deus temerás, a ele servirás, a ele te achegarás, e por seu nome jurarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 21, 'Ele é teu louvor, e ele é teu Deus, que fez contigo estas grandes e terríveis coisas que teus olhos viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 10, 22, 'Com setenta almas desceram teus pais ao Egito; e agora o SENHOR te fez como as estrelas do céu em multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 1, 'Amarás, pois, ao SENHOR teu Deus, e guardarás sua ordenança, e seus estatutos e seus regulamentos e seus mandamentos, todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 2, 'E compreendei hoje: porque não falo com vossos filhos que não souberam nem viram o castigo do SENHOR vosso Deus, sua grandeza, sua mão forte, e seu braço estendido,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 3, 'E seus sinais, e suas obras que fez em meio do Egito a Faraó, rei do Egito, e à toda sua terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 4, 'E o que fez ao exército do Egito, a seus cavalos, e a seus carros; como fez vir as águas do mar Vermelho sobre eles, quando vinham atrás vós, e o SENHOR os destruiu até hoje;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 5, 'E o que fez convosco no deserto, até que chegastes a este lugar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 6, 'E o que fez com Datã e Abirão, filhos de Eliabe filho de Rúben; como abriu a terra sua boca, e tragou-se a eles e a suas casas, e suas tendas, e toda a riqueza que tinham em pé em meio de todo Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 7, 'Mas vossos olhos viram todos os grandes feitos que o SENHOR executou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 8, 'Guardai, pois, todos os mandamentos que eu vos prescrevo hoje, para que sejais esforçados, e entreis e possuais a terra, à qual passais para possuí-la;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 9, 'E para que vos sejam prolongados os dias sobre a terra, que jurou o SENHOR a vossos pais havia de dar a eles e à sua descendência, terra que flui leite e mel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 10, 'Que a terra à qual entras para possuí-la, não é como a terra do Egito de onde saístes, onde semeavas tua semente, e regavas com teu pé, como jardim de hortaliça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 11, 'A terra à qual passais para possuí-la é terra de montes e de planícies; da chuva do céu ela bebe as águas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 12, 'terra da qual o SENHOR, teu Deus, cuida; os olhos do SENHOR, teu Deus, sempre estão sobre ela, do princípio do ano até o fim do ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 13, 'E será que, se obedecerdes cuidadosamente meus mandamentos que eu vos prescrevo hoje, amando ao SENHOR vosso Deus, e servindo-o com todo o vosso coração, e com toda vossa alma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 14, 'eu darei a chuva da vossa terra em seu tempo, a inicial e a tardia; e colherás teu grão, teu vinho, e teu azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 15, 'Darei também erva em teu campo para teus animais; e comerás, e te fartarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 16, 'Guardai-vos, pois, que vosso coração não se engane, e vos desvieis, e sirvais a deuses alheios, e vos inclineis a eles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 17, 'E assim se acenda o furor do SENHOR sobre vós, e feche os céus, e não haja chuva, nem a terra dê seu fruto, e pereçais logo da boa terra que vos dá o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 18, 'Portanto, poreis estas minhas palavras em vosso coração e em vossa alma, e as atareis por sinal em vossa mão, e serão por frontais entre vossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 19, 'E as ensinareis a vossos filhos, falando delas, ora sentado em tua casa, ou andando pelo caminho, quando te deites, e quando te levantes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 20, 'E as escreverás nos umbrais de tua casa, e em tuas entradas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 21, 'Para que sejam aumentados vossos dias, e os dias de vossos filhos, sobre a terra que jurou o SENHOR a vossos pais que lhes havia de dar, como os dias dos céus sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 22, 'Porque se guardardes cuidadosamente todos estes mandamentos que eu vos prescrevo, para que os cumprais; como ameis ao SENHOR vosso Deus andando em todos os seus caminhos, e a ele vos achegardes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 23, 'O SENHOR também expulsará todas estas nações de diante de vós e possuireis nações grandes e mais fortes que vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 24, 'Todo lugar que pisar a planta de vosso pé, será vosso: desde o deserto e o Líbano, desde o rio, o rio Eufrates, até o mar ocidental será vosso termo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 25, 'Ninguém resistirá diante de vós: medo e temor de vós porá o SENHOR vosso Deus sobre a face de toda a terra que pisardes, como ele vos disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 26, 'Eis que eu ponho hoje diante de vós a bênção e a maldição:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 27, 'A bênção, se ouvirdes os mandamentos do SENHOR vosso Deus, que eu vos prescrevo hoje;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 28, 'E a maldição, se não ouvirdes os mandamentos do SENHOR vosso Deus, e vos desviardes do caminho que eu vos ordeno hoje, para ir atrás de deuses alheios que não conhecestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 29, 'E será que, quando o SENHOR teu Deus te introduzir na terra à qual vais para possuí-la, porás a bênção sobre o monte Gerizim, e a maldição sobre o monte Ebal:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 30, 'Os quais estão da outra parte do Jordão, atrás do caminho do ocidente na terra dos cananeus, que habitam na campina diante de Gilgal, junto às planícies de Moré.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 31, 'Porque vós passais o Jordão, para ir a possuir a terra que vos dá o SENHOR vosso Deus; e a possuireis, e habitareis nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 11, 32, 'Cuidareis, pois, de pôr por obra todos os estatutos e direitos que eu apresento hoje diante de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 1, 'Estes são os estatutos e regulamentos que cuidareis de pôr por obra, na terra que o SENHOR o Deus de teus pais te deu para que a possuas, todos os dias que vós viverdes sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 2, 'Destruireis inteiramente todos os lugares onde as nações que vós herdardes serviram a seus deuses, sobre os montes altos, e sobre as colinas, e debaixo de toda árvore espessa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 3, 'E derrubareis seus altares, e quebrareis suas imagens, e seus bosques consumireis com fogo: e destruireis as esculturas de seus deuses, e extirpareis o nome delas daquele lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 4, 'Não fareis assim ao SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 5, 'Mas o lugar que o SENHOR vosso Deus escolher de todas as vossas tribos, para pôr ali seu nome para sua habitação, esse buscareis, e ali ireis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 6, 'E ali levareis vossos holocaustos, e vossos sacrifícios, e vossos dízimos, e a oferta elevada de vossas mãos, e vossos votos, e vossas ofertas voluntárias, e os primogênitos de vossas vacas e de vossas ovelhas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 7, 'E comereis ali diante do SENHOR vosso Deus, e vos alegrareis, vós e vossas famílias, em toda obra de vossas mãos em que o SENHOR teu Deus te houver abençoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 8, 'Não fareis como tudo o que nós fazemos aqui agora, cada um o que lhe parece,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 9, 'Porque ainda até agora não entrastes ao repouso e à herança que vos dá o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 10, 'Mas passareis o Jordão, e habitareis na terra que o SENHOR vosso Deus vos faz herdar, e ele vos dará repouso de todos vossos inimigos ao redor, e habitareis seguros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 11, 'E ao lugar que o SENHOR vosso Deus escolher para fazer habitar nele seu nome, ali levareis todas as coisas que eu vos mando: vossos holocaustos, e vossos sacrifícios, vossos dízimos, e as ofertas elevadas de vossas mãos, e todo o escolhido de vossos votos que houveres prometido ao SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 12, 'E vos alegrareis diante do SENHOR vosso Deus, vós, e vossos filhos, e vossas filhas, e vossos servos, e vossas servas, e o levita que estiver em vossas povoações: porquanto não tem parte nem herança convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 13, 'Guarda-te, que não ofereças teus holocaustos em qualquer lugar que vires;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 14, 'Mas no lugar que o SENHOR escolher, em uma de tuas tribos, ali oferecerás teus holocaustos, e ali farás tudo o que eu te mando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 15, 'Contudo, poderás matar e comer carne em todas tuas povoações conforme o desejo de tua alma, segundo a bênção do SENHOR teu Deus que ele te houver dado: o impuro e o limpo a comerá, como a de corço ou de cervo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 16, 'Salvo que sangue não comereis; sobre a terra o derramareis como água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 17, 'Nem poderás comer em tuas povoações o dízimo de teu grão, ou de teu vinho, ou de teu azeite, nem os primogênitos de tuas vacas, nem de tuas ovelhas, nem teus votos que prometeres, nem tuas ofertas voluntárias, nem as elevadas ofertas de tuas mãos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 18, 'Mas diante do SENHOR teu Deus as comerás, no lugar que o SENHOR teu Deus houver escolhido, tu, e teu filho, e tua filha, e teu servo, e tua serva, e o levita que está em tuas povoações: e te alegrarás diante do SENHOR teu Deus em toda obra de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 19, 'Tem cuidado de não desamparar ao levita em todos os teus dias sobre tua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 20, 'Quando o SENHOR teu Deus alargar teu termo, como ele te disse, e tu disseres: Comerei carne, porque desejou tua alma comê-la, conforme todo o desejo de tua alma comerás carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 21, 'Quando estiver longe de ti o lugar que o SENHOR teu Deus houver escolhido, para pôr ali seu nome, matarás de tuas vacas e de tuas ovelhas, que o SENHOR te houver dado, como te mandei eu, e comerás em tuas portas segundo tudo o que desejar tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 22, 'O mesmo que se come o corço e o cervo, assim as comerás: o impuro e o limpo comerão também delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 23, 'Somente que te esforces a não comer sangue: porque o sangue é a alma; e não hás de comer a alma juntamente com sua carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 24, 'Não o comerás: em terra o derramarás como água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 25, 'Não comerás dele; para que vá bem a ti, e a teus filhos depois de ti, quando fizeres o correto aos olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 26, 'Porém as coisas que tiveres tu consagradas, e teus votos, as tomarás, e virás ao lugar que o SENHOR houver escolhido:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 27, 'E oferecerás teus holocaustos, a carne e o sangue, sobre o altar do SENHOR teu Deus: e o sangue de teus sacrifícios será derramado sobre o altar do SENHOR teu Deus, e comerás a carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 28, 'Guarda e escuta todas estas palavras que eu te mando, porque vá bem a ti e a teus filhos depois de ti para sempre, quando fizeres o bom e o correto aos olhos do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 29, 'Quando houver devastado diante de ti o SENHOR teu Deus as nações aonde tu vais para possuí-las, e as herdares, e habitares em sua terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 30, 'Guarda-te que não tropeces seguindo-as, depois que forem destruídas diante de ti: não perguntes acerca de seus deuses, dizendo: Da maneira que serviam aquelas nações a seus deuses, assim farei eu também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 31, 'Não farás assim ao SENHOR teu Deus; porque tudo o que o SENHOR aborrece, fizeram eles a seus deuses; pois ainda a seus filhos e filhas queimavam no fogo a seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 12, 32, 'Cuidareis de fazer tudo o que eu vos mando: não acrescentarás a isso, nem tirarás disso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 1, 'Quando se levantar em meio de ti profeta, ou sonhador de sonhos, e te der sinal ou prodígio,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 2, 'E acontecer o sinal ou prodígio que ele te disse, dizendo: Vamos seguir deuses alheios, que não conheceste, e os sirvamos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 3, 'Não darás ouvido às palavras de tal profeta, nem ao tal sonhador de sonhos: porque o SENHOR vosso Deus vos prova, para saber se amais ao SENHOR vosso Deus com todo o vosso coração, e com toda vossa alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 4, 'Atrás do SENHOR vosso Deus andareis, e a ele temereis, e guardareis seus mandamentos, e escutareis sua voz, e a ele servireis, e a ele vos achegareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 5, 'E o tal profeta ou sonhador de sonhos, será morto; porquanto tratou de rebelião contra o SENHOR vosso Deus, que te tirou da terra do Egito, e te resgatou de casa de servos, e de tirar-te do caminho pelo que o SENHOR teu Deus te mandou que andasses; e assim tirarás o mal do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 6, 'Quando te incitar teu irmão, filho de tua mãe, ou teu filho, ou tua filha, ou a mulher de teu seio, ou teu amigo que seja como tua alma, dizendo em secreto: Vamos e sirvamos a deuses alheios, que nem tu nem teus pais conhecestes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 7, 'Aos deuses dos povos que estão em vossos arredores próximo a ti, ou longe de ti, desde um fim da terra até o outro fim dela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 8, 'Não consentirás com ele, nem lhe darás ouvido; nem teu olho o perdoará, nem terás compaixão, nem o encobrirás:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 9, 'Antes hás de matá-lo; tua mão será primeira sobre ele para matar-lhe, e depois a mão de todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 10, 'E hás de apedrejá-lo com pedras, e morrerá; porquanto procurou desviar-te do SENHOR teu Deus, que te tirou da terra do Egito, de casa de servos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 11, 'Para que todo Israel ouça, e tema, e não voltem a fazer coisa semelhante a esta má coisa em meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 12, 'Quando ouvires de alguma de tuas cidades que o SENHOR teu Deus te dá para que mores nelas, que se diz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 13, 'Homens, filhos de impiedade, saíram do meio de ti, que instigaram aos moradores de sua cidade, dizendo: Vamos e sirvamos a deuses alheios, que vós não conhecestes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 14, 'Tu investigarás, e buscarás, e preguntarás com empenho; e se parecer verdade, coisa certo, que tal abominação se fez em meio de ti,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 15, 'Invariavelmente ferirás a fio de espada os moradores daquela cidade, destruindo-a contudo o que nela houver, e também seus animais a fio de espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 16, 'E juntarás todo o despojo dela em meio de sua praça, e consumirás com fogo a cidade e todo seu despojo, todo ele, ao SENHOR teu Deus: e será um amontoado para sempre: nunca mais se edificará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 17, 'E não se pegará algo a tua mão do anátema; porque o SENHOR se afaste do furor de sua ira, e te dê compaixão, e tenha misericórdia de ti, e te multiplique, como o jurou a teus pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 13, 18, 'Quando obedeceres à voz do SENHOR teu Deus, guardando todos os seus mandamentos que eu te prescrevo hoje, para fazer o correto aos olhos do SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 1, 'Filhos sois do SENHOR vosso Deus: não vos cortareis, nem poreis calva sobre vossos olhos por morto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 2, 'Porque és povo santo ao SENHOR teu Deus, e o SENHOR te escolheu para que lhe sejas um povo singular dentre todos os povos que estão sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 3, 'Nada abominável comerás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 4, 'Estes são os animais que comereis: o boi, a ovelha, e a cabra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 5, 'O cervo, o corço, e o búfalo, e o bode selvagem, e o antílope, e boi selvagem, e cabra selvagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 6, 'E todo animal de unhas, que tem brecha de duas unhas, e que ruminar entre os animais, esse comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 7, 'Porém estes não comereis dos que ruminam, ou têm unha fendida: camelo, e lebre, e coelho, porque ruminam, mas não têm unha fendida, vos serão impuros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 8, 'Nem porco: porque tem unha fendida, mas não rumina, vos será impuro. Da carne destes não comereis, nem tocareis seus corpos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 9, 'Isto comereis de tudo o que está na água: todo o que tem barbatana e escama comereis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 10, 'Mas todo o que não tiver barbatana e escama, não comereis: impuro vos será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 11, 'Toda ave limpa comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 12, 'E estas são das que não comereis: a água, e o quebra-ossos, e o esmerilhão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 13, 'E o milhafre, e o abutre, e o falcão segundo sua espécie,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 14, 'E todo corvo segundo sua espécie,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 15, 'E o avestruz, e a coruja, e a gaivota, e o gavião segundo sua espécie,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 16, 'E o mocho, e o corujão, e a coruja-branca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 17, 'E o pelicano, e o gavião-pescador, e o corvo-marinho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 18, 'E a cegonha, e a garça segundo sua espécie, e a poupa, e o morcego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 19, 'E todo inseto de asas vos será impuro: não se comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 20, 'Toda ave limpa comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 21, 'Nenhuma coisa morta comereis: ao estrangeiro que está em tuas povoações a darás, e ele a comerá: ou vende-a ao estrangeiro; porque tu és povo santo ao SENHOR teu Deus. Não cozerás o cabrito no leite de sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 22, 'Indispensavelmente dizimarás todo o produto de tua semente, que render o campo cada ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 23, 'E comerás diante do SENHOR teu Deus no lugar que ele escolher para fazer habitar ali seu nome, o dízimo de teu grão, de teu vinho, e de teu azeite, e os primogênitos de tuas manadas, e de tuas gados, para que aprendas a temer ao SENHOR teu Deus todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 24, 'E se o caminho for tão longo que tu não possas levá-lo por ele, por estar longe de ti o lugar que o SENHOR teu Deus houver escolhido para pôr nele seu nome, quando o SENHOR teu Deus te abençoar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 25, 'Então o venderás, e atarás o dinheiro em tua mão, e virás ao lugar que o SENHOR teu Deus escolher;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 26, 'E darás o dinheiro por tudo o que desejar tua alma, por vacas, ou por ovelhas, ou por vinho, ou por bebida forte, ou por qualquer coisa que tua alma te pedir: e comerás ali diante do SENHOR teu Deus, e te alegrarás tu e tua família.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 27, 'E não desampararás ao levita que habitar em tuas povoações; porque não tem parte nem herança contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 28, 'Ao fim de cada três anos tirarás todo o dízimo de teus produtos daquele ano, e o guardarás em tuas cidades:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 14, 29, 'E virá o levita, que não tem parte nem herança contigo, e o estrangeiro, e o órfão, e a viúva, que houver em tuas povoações, e comerão e serão saciados; para que o SENHOR teu Deus te abençoe em toda obra de tuas mãos que fizeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 1, 'Ao fim de sete anos farás remissão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 2, 'E esta é a maneira da remissão: perdoará a seu devedor todo aquele que fez empréstimo de sua mão, com que obrigou a seu próximo: não o exigirá mais a seu próximo, ou a seu irmão; porque a remissão do SENHOR é proclamada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 3, 'Do estrangeiro exigirás o pagamento: mas o que teu irmão tiver teu, o perdoará tua mão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 4, 'Para que assim não haja em ti pobre; porque o SENHOR te abençoará com abundância na terra que o SENHOR teu Deus te dá por herança para que a possuas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 5, 'Se porém escutares fielmente a voz do SENHOR teu Deus, para guardar e cumprir todos estes mandamentos que eu te intimo hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 6, 'Já que o SENHOR teu Deus te haverá abençoado, como te disse, emprestarás então a muitas nações, mas tu não tomarás emprestado; e te ensenhorearás de muitas nações, mas de ti não se ensenhorearão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 7, 'Quando houver em ti necessitado de algum de teus irmãos em alguma de tuas cidades, em tua terra que o SENHOR teu Deus te dá, não endurecerás teu coração, nem fecharás tua mão a teu irmão pobre:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 8, 'Mas abrirás a ele tua mão generosamente, e com efeito lhe emprestarás o que basta, o que houver necessidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 9, 'Guarda-te que não haja em teu coração perverso pensamento, dizendo: Próximo está o ano sétimo, o da remissão; e tua olho seja maligno sobre teu irmão necessitado para não dar-lhe: que ele poderá clamar contra ti ao SENHOR, e se te imputará a pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 10, 'Sem falta lhe darás, e não seja teu coração maligno quando lhe deres: que por ele te abençoará o SENHOR teu Deus em todos os teus feitos, e em tudo o que puseres mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 11, 'Porque não faltarão necessitados do meio da terra; por isso eu te mando, dizendo: Abrirás tua mão a teu irmão, a teu pobre, e a teu necessitado em tua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 12, 'Quando se vender a ti teu irmão hebreu ou hebreia, e te houver servido seis anos, ao sétimo ano lhe despedirás livre de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 13, 'E quando o despedires livre de ti, não o enviarás vazio:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 14, 'Tu lhe abastecerás generosamente de tuas ovelhas, de tua eira, e de tua prensa de uvas; tu lhe darás daquilo em que o SENHOR te houver abençoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 15, 'E te lembrarás que foste servo na terra do Egito, e que o SENHOR teu Deus te resgatou: portanto eu te mando isto hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 16, 'E será que, se ele te disser: Não sairei de tua presença; porque ama a ti e à tua casa, que lhe vai bem contigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 17, 'Então tomarás uma ferramenta pontiaguda, e furarás sua orelha junto à porta, e será teu servo para sempre: assim também farás à tua criada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 18, 'Não te pareça duro quando lhe enviares livre de ti; que dobrado do salário de jovem assalariado te serviu seis anos: e o SENHOR teu Deus te abençoará em tudo quanto fizeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 19, 'Santificarás ao SENHOR teu Deus todo primeiro macho que nascer de tuas vacas e de tuas ovelhas: não te sirvas do primeiro de tuas vacas, nem tosquies o primeiro de tuas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 20, 'Diante do SENHOR teu Deus os comerás cada ano, tu e tua família, no lugar que o SENHOR escolher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 21, 'E se houver nele mácula, cego ou coxo, ou qualquer má falta, não o sacrificarás ao SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 22, 'Em tuas povoações o comerás: o impuro o mesmo que o limpo comerão dele, como de um corço ou de um cervo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 15, 23, 'Somente que não comas seu sangue: sobre a terra a derramarás como água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 1, 'Guardarás o mês de Abibe, e farás páscoa ao SENHOR teu Deus: porque no mês de Abibe te tirou o SENHOR teu Deus do Egito de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 2, 'E sacrificarás a páscoa ao SENHOR teu Deus, das ovelhas e das vacas, no lugar que o SENHOR escolher para fazer habitar ali seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 3, 'Não comerás com ela levedado; sete dias comerás com ela pão sem levedar, pão de aflição, porque apressadamente saíste da terra do Egito: para que te lembres do dia em que saíste da terra do Egito todos os dias de tua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 4, 'E não se deixará ver levedura contigo em todo teu termo por sete dias; e da carne que matares à tarde do primeiro dia, não ficará até a manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 5, 'Não poderás sacrificar a páscoa em nenhuma de tuas cidades, que o SENHOR teu Deus te dá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 6, 'Mas sim no lugar que o SENHOR teu Deus escolher para fazer habitar ali seu nome, sacrificarás a páscoa pela tarde ao pôr do sol, ao tempo que saíste do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 7, 'E a assarás e comerás no lugar que o SENHOR teu Deus houver escolhido; e pela manhã te voltarás e irás à tua morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 8, 'Seis dias comerás pães ázimos, e no sétimo dia será solenidade ao SENHOR teu Deus: não farás obra nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 9, 'Sete semanas te contarás: desde que começar a foice nas plantações de grãos começarás a contar as sete semanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 10, 'E farás a solenidade das semanas ao SENHOR teu Deus: da suficiência voluntária de tua mão será o que deres, segundo o SENHOR teu Deus te houver abençoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 11, 'E te alegrarás diante do SENHOR teu Deus, tu, e teu filho, e tua filha, e teu servo, e tua serva, e o levita que estiver em tuas cidades, e o estrangeiro, e o órfão, e a viúva, que estiverem em meio de ti, no lugar que o SENHOR teu Deus houver escolhido para fazer habitar ali o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 12, 'E lembra-te que foste servo no Egito; portanto guardarás e cumprirás estes estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 13, 'A solenidade das cabanas farás por sete dias, quando houveres feito a colheita de tua eira e de tua prensa de uvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 14, 'E te alegrarás em tuas solenidades, tu, e teu filho, e tua filha, e teu servo, e tua serva, e o levita, e o estrangeiro, e o órfão, e a viúva, que estão em tuas povoações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 15, 'Sete dias celebrarás solenidade ao SENHOR teu Deus no lugar que o SENHOR escolher; porque te haverá abençoado o SENHOR teu Deus em todos os teus frutos, e em toda obra de tuas mãos, e estarás certamente alegre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 16, 'Três vezes cada ano comparecerá todo homem teu diante do SENHOR teu Deus no lugar que ele escolher: na solenidade dos pães ázimos, e na solenidade das semanas, e na solenidade das cabanas. E não comparecerá vazio diante do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 17, 'Cada um com a doação de sua mão, conforme a bênção do SENHOR teu Deus, que te houver dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 18, 'Juízes e oficiais te porás em todas tuas cidades que o SENHOR teu Deus te dará em tuas tribos, os quais julgarão ao povo com justo juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 19, 'Não distorças o direito; não faças acepção de pessoas, nem tomes suborno; porque o suborno cega os olhos dos sábios, e perverte as palavras dos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 20, 'A justiça, a justiça seguirás, para que vivas e herdes a terra que o SENHOR teu Deus te dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 21, 'Não plantarás árvore que sirva de mastro de idolatria junto ao altar do SENHOR, teu Deus, que fizeres para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 16, 22, 'Nem levantarás para ti coluna sagrada de pedra, a qual o SENHOR, teu Deus, odeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 1, 'Não sacrificarás ao SENHOR teu Deus boi, ou cordeiro, no qual haja falta ou alguma coisa má: porque é abominação ao SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 2, 'Quando se achar entre ti, em alguma de tuas cidades que o SENHOR teu Deus te dá, homem, ou mulher, que tenha feito mal aos olhos do SENHOR teu Deus transgredido seu pacto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 3, 'Que houver ido e servido a deuses alheios, e se houver inclinado a eles, ora ao sol, ou à lua, ou a todo o exército do céu, o qual eu não mandei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 4, 'E te for dado aviso, e, depois que ouvires e houveres indagado bem, a coisa parece de verdade certa, que tal abominação foi feita em Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 5, 'Então tirarás ao homem ou mulher que houver feito esta má coisa, a tuas portas, homem ou mulher, e os apedrejarás com pedras, e assim morrerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 6, 'Por dito de duas testemunhas, ou de três testemunhas, morrerá o que houver de morrer; não morrerá pelo dito de uma só testemunha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 7, 'A mão das testemunhas será primeira sobre ele para matá-lo, e depois a mão de todo o povo: assim tirarás o mal do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 8, 'Quando alguma coisa te for oculta em juízo entre sangue e sangue, entre causa e causa, e entre chaga e chaga, em negócios de litigio em tuas cidades; então te levantarás e recorrerás ao lugar que o SENHOR teu Deus escolher;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 9, 'E virás aos sacerdotes levitas, e ao juiz que for naqueles dias, e preguntarás; e te ensinarão a sentença do juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 10, 'E farás segundo a sentença que te indicarem os do lugar que o SENHOR escolher, e cuidarás de fazer segundo tudo o que te manifestarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 11, 'Segundo a lei que eles te ensinarem, e segundo o juízo que te disserem, farás: não te desviarás nem à direita nem à esquerda da sentença que te mostrarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 12, 'E o homem que proceder com soberba, não obedecendo ao sacerdote que está para ministrar ali diante do SENHOR teu Deus, ou ao juiz, o tal homem morrerá: e tirarás o mal de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 13, 'E todo o povo ouvirá, e temerá, e não se ensoberbecerão mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 14, 'Quando houveres entrado na terra que o SENHOR teu Deus te dá, e a possuíres, e habitares nela, e disseres: Porei rei sobre mim, como todas as nações que estão em meus arredores;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 15, 'Sem dúvida porás por rei sobre ti ao que o SENHOR teu Deus escolher: dentre teus irmãos porás rei sobre ti: não poderás pôr sobre ti homem estrangeiro, que não seja teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 16, 'Porém que não se aumente cavalos, nem faça voltar o povo ao Egito para acrescentar cavalos: porque o SENHOR vos disse: Não procurareis voltar mais por este caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 17, 'Nem aumentará para si mulheres, para que seu coração não se desvie: nem prata nem ouro acrescentará para si em grande quantidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 18, 'E será, quando se assentar sobre o trono de seu reino, que há de escrever para si em um livro uma cópia desta lei, do original de diante dos sacerdotes levitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 19, 'E o terá consigo, e lerá nele todos os dias de sua vida, para que aprenda a temer ao SENHOR seu Deus, para guardar todas as palavras desta lei e estes estatutos, para praticá-los:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 17, 20, 'Para que não se eleve seu coração sobre seus irmãos, nem se desvie do mandamento à direita nem à esquerda; a fim que prolongue seus dias em seu reino, ele e seus filhos, em meio de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 1, 'Os sacerdotes levitas, toda a tribo de Levi, não terão parte nem herança com Israel; das ofertas acendidas ao SENHOR, e da herança dele comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 2, 'Não terão, pois, herança entre seus irmãos: o SENHOR é a sua herança, como ele lhes disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 3, 'E este será o direito dos sacerdotes da parte do povo, dos que oferecerem em sacrifício boi ou cordeiro: darão ao sacerdote a retaguarda, e as queixadas, e o estômago.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 4, 'As primícias de teus grãos, de teu vinho, e de teu azeite, e as primícias da lã de tuas ovelhas lhe darás:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 5, 'Porque o escolheu o SENHOR teu Deus de todas tuas tribos, para que esteja para ministrar ao nome do SENHOR, ele e seus filhos para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 6, 'E quando o levita sair de alguma de tuas cidades de todo Israel, onde houver peregrinado, e vier com todo desejo de sua alma ao lugar que o SENHOR escolher,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 7, 'Ministrará ao nome do SENHOR seu Deus, como todos os seus irmãos os levitas que estiverem ali diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 8, 'Porção como a porção dos outros comerão, além de seus patrimônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 9, 'Quando houveres entrado na terra que o SENHOR teu Deus te dá, não aprenderás a fazer segundo as abominações daquelas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 10, 'Não seja achado em ti quem faça passar seu filho ou sua filha pelo fogo, nem praticante de adivinhações, nem agoureiro, nem interpretador de presságios, nem feiticeiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 11, 'Nem quem fale encantamentos, nem quem pergunte a espírito, nem mágico, nem quem pergunte aos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 12, 'Porque é abominação ao SENHOR qualquer um que faz estas coisas, e por estas abominações o SENHOR teu Deus as expulsou de diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 13, 'Serás íntegro com o SENHOR teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 14, 'Pois essas nações que herdarás ouviam encantadores e feiticeiros. A ti, porém, o SENHOR teu Deus não te permitiu isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 15, 'O SENHOR teu Deus suscitará para ti um Profeta do meio de ti, de teus irmãos, como eu; a ele deverás ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 16, 'Conforme tudo o que pediste ao SENHOR teu Deus em Horebe no dia da assembleia, dizendo: Não volte eu a ouvir a voz do SENHOR meu Deus, nem veja eu mais este grande fogo, para que não morra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 17, 'e o SENHOR me disse: Bem disseram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 18, 'Profeta lhes suscitarei do meio de seus irmãos, como tu; e porei minhas palavras em sua boca, e ele lhes falará tudo o que eu lhe mandar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 19, 'Mas será, que qualquer um que não ouvir minhas palavras que ele falar em meu nome, eu lhe exigirei prestar contas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 20, 'Porém o profeta que presumir falar palavra em meu nome, que eu não lhe tenha mandado falar, ou que falar em nome de deuses alheios, o tal profeta morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 21, 'E se disseres em teu coração: Como conheceremos a palavra que o SENHOR não houver falado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 18, 22, 'Quando o profeta falar em nome do SENHOR, e não for a tal coisa, nem vier, é palavra que o SENHOR não falou: com soberba a falou aquele profeta: não tenhas medo dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 1, 'Quando o SENHOR teu Deus exterminar as nações, cuja terra o SENHOR teu Deus dá a ti, e tu as herdares, e habitares em suas cidades, e em suas casas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 2, 'Separarás três cidades em meio de tua terra que o SENHOR teu Deus te dá para que a possuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 3, 'Prepararás o caminho, e dividirás em três partes o termo de tua terra, que o SENHOR teu Deus te dará em herança, e será para que todo homicida se fuja ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 4, 'E este é o caso do homicida que há de fugir ali, e viverá: o que ferir a seu próximo por acidente, que não lhe tinha inimizade nem recente nem em passado distante:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 5, 'Como o que foi com seu próximo ao monte a cortar lenha, e pondo força com sua mão no machado para cortar alguma lenha, saltou o ferro do fim, e encontrou a seu próximo, e morreu; aquele fugirá a uma daquelas cidades, e viverá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 6, 'Não seja que o parente do morto vá atrás do homicida, quando se arder seu coração, e o alcance por ser longo o caminho, e o fira de morte, não devendo ser condenado à morte; porquanto não tinha inimizade nem recente nem em passado distante com o morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 7, 'Portanto eu te mando, dizendo: Três cidades separarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 8, 'E se o SENHOR teu Deus alargar teu termo, como o jurou a teus pais, e te der toda a terra que disse a teus pais que havia de dar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 9, 'Quando guardasses todos estes mandamentos, que eu te prescrevo hoje, para praticá-los, que ames ao SENHOR teu Deus e andes em seus caminhos todos os dias, então acrescentarás três cidades a mais destas três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 10, 'Para que não seja derramado sangue inocente em meio de tua terra, que o SENHOR teu Deus te dá por herança, e seja sobre ti sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 11, 'Mas quando houver alguém que aborrecer a seu próximo, e o espreitar, e se levantar sobre ele, e o ferir de morte, e morrer, e fugir a alguma destas cidades;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 12, 'Então os anciãos de sua cidade enviarão e o tirarão dali, e o entregarão em mão do parente do morto, e morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 13, 'Não lhe perdoará teu olho: e tirarás de Israel o sangue inocente, e te irá bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 14, 'Não reduzirás o termo de teu próximo, o qual assinalaram os antigos em tua herança, a que possuíres na terra que o SENHOR teu Deus te dá para que a possuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 15, 'Não valerá uma testemunha contra ninguém em qualquer delito, ou em qualquer pecado, em qualquer pecado que se cometer. No dito de duas testemunhas, ou no dito de três testemunhas consistirá o negócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 16, 'Quando se levantar testemunha falso contra alguém, para testificar contra ele rebelião,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 17, 'Então os dois homens litigantes se apresentarão diante do SENHOR, diante dos sacerdotes e juízes que forem naqueles dias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 18, 'E os juízes investigarão bem, e se parecer ser aquela testemunha falsa, que testificou falsamente contra seu irmão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 19, 'Fareis a ele como ele pensou fazer a seu irmão: e tirarás o mal do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 20, 'E os que restarem ouvirão, e temerão, e não voltarão mais a fazer uma má coisa como esta, em meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 19, 21, 'E não perdoará teu olho: vida por vida, olho por olho, dente por dente, mão por meio, pé por pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 1, 'Quando saíres à guerra contra teus inimigos, e vires cavalos e carros, um povo maior que tu, não tenhas medo deles, que o SENHOR teu Deus é contigo, o qual te tirou da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 2, 'E será que, quando vos aproximardes para combater, chegará o sacerdote, e falará ao povo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 3, 'E lhes dirá: Ouve, Israel, vós vos juntais hoje em batalha contra vossos inimigos: não se amoleça vosso coração, não temais, não vos alarmeis, nem tampouco vos desanimeis diante deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 4, 'Que o SENHOR vosso Deus anda convosco, para lutar por vós contra vossos inimigos, para vos salvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 5, 'E os oficiais falarão ao povo, dizendo: Quem edificou casa nova, e não a dedicou? Vá, e volte-se à sua casa, para que talvez não morra na batalha, e outro algum a dedique.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 6, 'E quem plantou vinha, e não fez comum uso dela? Vá, e volte-se à sua casa, para que talvez não morra na batalha, e outro alguém a desfrute.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 7, 'E quem se desposou com mulher, e não a tomou? Vá, e volte-se à sua casa, para que talvez não morra na batalha, e algum outro a tome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 8, 'E tornarão os oficiais a falar ao povo, e dirão: Quem é homem medroso e tenro de coração? Vá, e volte-se à sua casa, e não derreta o coração de seus irmãos, como seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 9, 'E será que, quando os oficiais acabarem de falar ao povo, então os capitães dos exércitos mandarão diante do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 10, 'Quando te aproximares a uma cidade para combatê-la, lhe oferecerás a paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 11, 'E será que, se te responder, Paz, e te abrir, todo o povo que nela for achado te serão tributários, e te servirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 12, 'Mas se não fizer paz contigo, e empreender contigo guerra, e a cercares,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 13, 'Logo que o SENHOR teu Deus a entregar em tua mão, ferirás a todo homem seu a fio de espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 14, 'Somente as mulheres e as crianças, e os animais, e todo o que houver na cidade, todos os seus despojos, tomarás para ti: e comerás do despojo de teus inimigos, os quais o SENHOR teu Deus te entregou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 15, 'Assim farás a todas as cidades que estiverem muito longe de ti, que não forem das cidades destas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 16, 'Porém das cidades destes povos que o SENHOR teu Deus te dá por herança, nenhuma pessoa deixarás com vida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 17, 'Antes por completo os destruirás: aos heteus, e aos amorreus, e aos cananeus, e aos perizeus, e aos heveus, e aos jebuseus; como o SENHOR teu Deus te mandou:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 18, 'Para que não vos ensinem a fazer segundo todas suas abominações, que eles fazem a seus deuses, e pequeis contra o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 19, 'Quando puseres cerco a alguma cidade, lutando contra ela muitos dias para tomá-la, não destruas seu arvoredo metendo nele machado, porque dele comerás; e não o cortarás, que não é homem a árvore do campo para vir contra ti no cerco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 20, 20, 'Mas a árvore que souberes que não é árvore para comer, o destruirás e o cortarás, e constrói baluarte contra a cidade que luta contigo, até subjugá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 1, 'Quando for achado na terra que o SENHOR teu Deus te dá para que a possuas, morto deitado no campo, e não se soubesse quem o feriu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 2, 'Então teus anciãos e teus juízes sairão e medirão até as cidades que estão ao redor do morto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 3, 'E será que os anciãos daquela cidade, da cidade mais próxima ao morto, tomarão das vacas uma bezerra que não tenha servido, que não tenha trazido jugo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 4, 'E os anciãos daquela cidade trarão a bezerra a um vale por onde fluam águas, que nunca tenha sido arado nem semeado, e cortarão o pescoço à bezerra ali no vale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 5, 'Então virão os sacerdotes filhos de Levi, porque a eles escolheu o SENHOR teu Deus para que o sirvam, e para abençoar em nome do SENHOR; e pelo dito deles se determinará todo pleito e toda ferida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 6, 'E todos os anciãos daquela cidade mais próxima ao morto lavarão suas mãos sobre a bezerra degolada no vale.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 7, 'E protestarão, e dirão: Nossas mãos não derramaram este sangue, nem nossos olhos o viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 8, 'Expia a teu povo Israel, ao qual redimiste, ó SENHOR; e não imputes o sangue inocente derramado em meio de teu povo Israel. E o sangue lhes será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 9, 'E tu tirarás a culpa de sangue inocente do meio de ti, quando fizeres o que é correto aos olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 10, 'Quando saíres à guerra contra teus inimigos, e o SENHOR teu Deus os entregar em tua mão, e tomares deles cativos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 11, 'E vires entre os cativos alguma mulher bela, e a cobiçares, e a tomares para ti por mulher,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 12, 'Tu a meterás em tua casa; e ela rapará sua cabeça, e cortará suas unhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 13, 'E se tirará a roupa de seu cativeiro, e ficará em tua casa: e chorará a seu pai e a sua mãe no tempo de um mês: e depois entrarás a ela, e tu serás seu marido, e ela tua mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 14, 'E será, se não te agradar, que a deixarás em sua liberdade; e não a venderás por dinheiro, nem farás comércio dela, porquanto a afligiste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 15, 'Quando um homem tiver duas mulheres, uma amada e a outra aborrecida, e a amada e a aborrecida lhe derem à luz filhos, e o filho primogênito for da aborrecida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 16, 'Será que, no dia que fizer herdar a seus filhos o que tiver, não poderá dar o direito de primogenitura aos filhos da amada em preferência ao filho da aborrecida, que é o primogênito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 17, 'Mas ao filho da aborrecida reconhecerá por primogênito, para dar-lhe dois tantos de tudo o que se achar que tem: porque aquele é o princípio de sua força, o direito da primogenitura é seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 18, 'Quando alguém tiver filho obstinado e rebelde, que não obedecer à voz de seu pai nem à voz de sua mãe, e havendo-o castigado, não lhes obedecer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 19, 'Então o tomarão seu pai e sua mãe, e o tirarão aos anciãos de sua cidade, e à porta do lugar seu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 20, 'E dirão aos anciãos da cidade: Este nosso filho é obstinado e rebelde, não obedece à nossa voz; é comilão e beberrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 21, 'Então todos os homens de sua cidade o apedrejarão com pedras, e morrerá: assim tirarás o mal do meio de ti; e todo Israel ouvirá, e temerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 22, 'Quando em alguém houver pecado de sentença de morte, pelo que haja de morrer, e lhe houverdes pendurado em um madeiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 21, 23, 'Não estará seu corpo pela noite no madeiro, mas sem falta o enterrarás no mesmo dia, porque maldição de Deus é o pendurado: e não contaminarás tua terra, que o SENHOR teu Deus te dá por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 1, 'Não verás o boi de teu irmão, ou seu cordeiro, perdidos, e te retirarás deles: precisamente os devolverás a teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 2, 'E se teu irmão não for teu vizinho, ou não lhe conheceres, os recolherás em tua casa, e estarão contigo até que teu irmão os busque, e os devolverás a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 3, 'E assim farás de seu asno, assim farás também de sua roupa, e o mesmo farás com toda coisa perdida de teu irmão que se lhe perder, e tu a achares: não poderás te omitir quanto a isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 4, 'Não verás o asno de teu irmão, ou seu boi, caídos no caminho, e te esconderás deles: com ele hás de procurar levantá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 5, 'Não vestirá a mulher roupa de homem, nem o homem vestirá roupa de mulher; porque abominação é ao SENHOR teu Deus qualquer um que isto faz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 6, 'Quando achares no caminho algum ninho de ave em qualquer árvore, ou sobre a terra, com passarinhos ou ovos, e estiver a mãe reclinada sobre os passarinhos ou sobre os ovos, não tomes a mãe com os filhos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 7, 'Deixarás ir à mãe, e tomarás os passarinhos para ti; para que te vá bem, e prolongues teus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 8, 'Quando edificares casa nova, farás parapeito em teu terraço, para que não ponhas sangue em tua casa, se dele cair alguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 9, 'Não semearás tua vinha de várias sementes, para que não se deprave a plenitude da semente que semeaste, e o fruto da vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 10, 'Não ararás com boi e com asno juntamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 11, 'Não te vestirás de mistura, de lã e linho juntamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 12, 'Farás para ti franjas nos quatro extremos de teu manto com que te cobrires.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 13, 'Quando alguém tomar mulher, e depois de haver entrado a ela a aborrecer,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 14, 'E lhe puser algumas faltas, e espalhar sobre ela má fama, e disser: Esta tomei por mulher, e cheguei a ela, e não a achei virgem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 15, 'Então o pai da moça e sua mãe tomarão, e tirarão os sinais da virgindade da virgem aos anciãos da cidade, na porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 16, 'E dirá o pai da moça aos anciãos: Eu dei minha filha a este homem por mulher, e ele a aborrece;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 17, 'E, eis que, ele lhe põe acusações de algumas coisas, dizendo: Não achei tua filha virgem; porém, eis aqui os sinais da virgindade de minha filha. E estenderão o lençol diante dos anciãos da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 18, 'Então os anciãos da cidade tomarão ao homem e o castigarão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 19, 'E lhe hão de impor pena em cem peças de prata, as quais darão ao pai da moça, porquanto espalhou má fama sobre virgem de Israel: e a há de ter por mulher, e não poderá despedi-la em todos os seus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 20, 'Mas se este negócio foi verdade, que não se houver achado virgindade na moça,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 21, 'Então a tirarão à porta da casa de seu pai, e a apedrejarão com pedras os homens de sua cidade, e morrerá; porquanto fez depravação em Israel prostituindo-se em casa de seu pai: assim tirarás o mal do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 22, 'Quando se surpreender alguém deitado com mulher casada com marido, ambos morrerão, o homem que se deitou com a mulher, e a mulher: assim tirarás o mal de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 23, 'Quando for moça virgem desposada com alguém, e alguém a achar na cidade, e se deixar com ela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 24, 'Então os tirareis a ambos à porta daquela cidade, e os apedrejareis com pedras, e morrerão; a moça porque não gritou na cidade, e o homem porque humilhou à mulher de seu próximo: assim tirarás o mal do meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 25, 'Mas se o homem achou uma moça desposada no campo, e ele a agarrar, e se deitar com ela, morrerá somente o homem que com ela se houver deitado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 26, 'E à moça não farás nada; não tem a moça culpa de morte: porque como quando alguém se levanta contra seu próximo, e lhe tira a vida, assim é isto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 27, 'Porque ele a achou no campo: gritou a moça desposada, e não houve quem a protegesse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 28, 'Quando alguém achar moça virgem, que não for desposada, e a tomar, e se deitar com ela, e forem achados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 22, 29, 'Então o homem que se deitou com ela dará ao pai da moça cinquenta peças de prata, e ela será sua mulher, porquanto a humilhou: não a poderá despedir em todos os seus dias.')
